with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1po127kp04f', 'practice', 'Oral A1 : à la boulangerie', 'A1', array['Production orale']::text[], 'practice', null, null, '<p>Vous jouez le client. Regardez les prix. Enregistrez-vous : dites chaque phrase de votre rôle.</p>', '<div class="mcf-bang"><table><thead><tr><th>Produit</th><th>Prix</th></tr></thead><tbody><tr><td>une baguette</td><td>1 €</td></tr><tr><td>un croissant</td><td>1,20 €</td></tr><tr><td>un pain au chocolat</td><td>1,50 €</td></tr><tr><td>une tarte</td><td>12 €</td></tr></tbody></table></div>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une boulangerie (nom féminin) : tiệm bánh\n• je voudrais (expression) : tôi muốn\n• c''est combien ? (expression) : bao nhiêu tiền?\n• je prends (expression) : tôi lấy\n• voilà (expression) : đây ạ","explications":"• Đi đủ bốn bước: chào, hỏi, trả tiền, cảm ơn.\n• Tính đúng tiền: 1 € + 2 × 1,20 € = 3,40 €.","ghiAm":true,"kyNang":"A1-PO-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T14:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxqs7kl01q', 'a1po127kp04f', 1, 'open', 'Saluez la vendeuse et demandez une baguette.', '{}'::jsonb, '{"model":"Bonjour madame, je voudrais une baguette, s''il vous plaît."}'::jsonb, null), ('qmvxqs7kl01r', 'a1po127kp04f', 2, 'open', 'Demandez le prix d''un croissant.', '{}'::jsonb, '{"model":"C''est combien, un croissant ?"}'::jsonb, null), ('qmvxqs7kl01s', 'a1po127kp04f', 3, 'open', 'Vous prenez deux croissants.', '{}'::jsonb, '{"model":"Je prends deux croissants, s''il vous plaît."}'::jsonb, null), ('qmvxqs7kl01t', 'a1po127kp04f', 4, 'open', 'Vous payez et vous partez.', '{}'::jsonb, '{"model":"Voilà trois euros quarante. Merci, au revo