with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1po187kq04l', 'practice', 'Oral A1 : bonjour, merci', 'A1', array['Production orale']::text[], 'practice', null, null, '<p>Choisissez la bonne phrase pour chaque situation. Puis enregistrez-vous pour la dernière situation.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• bonjour (interjection) : xin chào\n• bonsoir (interjection) : chào buổi tối\n• de rien (expression) : không có gì\n• enchanté, enchantée (adjectif) : rất vui được gặp\n• à demain (expression) : hẹn mai gặp","explications":"• Bonjour dùng ban ngày, bonsoir dùng buổi tối.\n• Vào cửa hàng ở Pháp luôn chào trước.","ghiAm":true,"kyNang":"A1-PO-4","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T14:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxqs7km02e', 'a1po187kq04l', 1, 'qcm', 'Vous entrez dans un magasin le matin.', '{"options":["Au revoir madame.","Bonsoir madame.","Bonjour madame."]}'::jsonb, '{"answer":2}'::jsonb, 'Buổi sáng, khi đến: Bonjour.'), ('qmvxqs7km02f', 'a1po187kq04l', 2, 'qcm', 'Quelqu''un vous aide.', '{"options":["Pardon.","Merci beaucoup.","S''il vous plaît."]}'::jsonb, '{"answer":1}'::jsonb, 'Cảm ơn: Merci beaucoup.'), ('qmvxqs7km02g', 'a1po187kq04l', 3, 'qcm', 'On vous dit merci.', '{"options":["Bonjour.","Excusez-moi.","De rien."]}'::jsonb, '{"answer":2}'::jsonb, 'Đáp lại lời cảm ơn: De rien.'), ('qmvxqs7km02h', 'a1po187kq04l', 4, 'qcm', 'Vous partez le soir.', '{"options":["Bonjour !","Enchanté !","Bonsoir, bonne soirée !"]}'::jsonb, '{"answer":2}'::jsonb, 'Buổi tối: Bonsoir, bonne soirée.'), ('qmvxqs7km02i', 'a1po187kq04l', 5, 'qcm', 'Vous rencontrez une personne pour la première fois.', '{"options":["Enchanté.","De rien.","À demain."]}'::jsonb, '{"answer":0}'::jsonb, 'Gặp lần đầu: Enchanté.'), ('qmvxqs7km02j', 'a1po187kq04l', 6, 'open', 'Dites bonjour à votre voisine et demandez comment elle va.', '{}'::jsonb, '{"model":"Bonjour madame, comment allez-vous ?"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
