Bonjour monsieur.","Coucou !","Salut !"]}'::jsonb, '{"answer":0}'::jsonb, 'Salut chỉ dùng với người thân.'), ('qmvxqs7km02p', 'a1po197kq04m', 6, 'open', 'Demandez poliment à un inconnu où est la gare.', '{}'::jsonb, '{"model":"Excusez-moi monsieur, où est la gare, s''il vous plaît ?"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1po207kq04n', 'practice', 'Oral A1 : s''il vous plaît, excusez-moi', 'A1', array['Production orale']::text[], 'practice', null, null, '<p>Choisissez la bonne phrase pour chaque situation. Puis enregistrez-vous pour la dernière situation.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• s''il vous plaît (expression) : làm ơn\n• excusez-moi (expression) : xin lỗi\n• pardon (nom masculin) : xin lỗi\n• en retard (expression) : muộn\n• je ne comprends pas (expression) : tôi không hiểu","explications":"• Câu xin ngắn vẫn cần s''il vous plaît.\n• Pouvez-vous répéter ? là câu cứu nguy trong phòng thi.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"A1-PO-4","vong":"on","thuTu":3}'::jsonb, '2026-11-01T14:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxqs7km02q', 'a1po207kq04n', 1, 'qcm', 'Vous voulez un café.', '{"options":["Café !","Donne un café.","Un café, s''il vous plaît."]}'::jsonb, '{"answer":2}'::jsonb, 'Thêm s''il vous plaît khi xin.'), ('qmvxqs7km02r', 'a1po207kq04n', 2, 'qcm', 'Vous êtes en retard.', '{"options":["Excusez-moi, je suis en retard.","Merci, je suis en retard.","Bonjour, à demain."]}'::jsonb, '{"answer":0}'::jsonb, 'Xin lỗi: Excusez-moi.'), ('qmvxqs7km02s', 'a1po207kq04n', 3, 'qcm', 'Vous marchez sur le pied de quelqu''un.', '{"options":["Enchanté !","Pardon !","Bon appétit !"]}'::jsonb, '{"answer":1}'::jsonb, 'Xin lỗi nhanh: Pardon.'), ('qmvxqs7km02t', 'a1po207kq04n', 4, 'qcm', 'Vous ne comprenez pas.', '{"options":["Merci, c''est tout.","Je comprends. Au revoir.","Je ne comprends pas. Pouvez-vous répéter ?"]}'::jsonb, '{"answer":2}'::jsonb, 'Không hiểu thì xin nhắc lại.'), ('qmvxqs7km02u', 'a1po207kq04n', 5, 'qcm', 'Vous voulez passer.', '{"options":["Bonsoir, je mange.","Pardon, je peux passer ?","Passe !"]}'::jsonb, '{"answer":1}'::jsonb, 'Xin đi qua: Pardon, je peux passer ?'), ('qmvxqs7km02v', 'a1po207kq04n', 6, 'open', 'Vous arrivez en retard au cours. Excusez-vous auprès du professeur.', '{}'::jsonb, '{"model":"Excusez-moi madame, je suis en retard. Le bus n''arrive pas."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
